function validate([root]) {
  if (!root.length || root[0] === null) return 'The tree needs at least 1 node.';
  const values = root.filter(v => v !== null);
  if (values.length > 40000) return 'The tree has at most 40000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -40000 || v > 40000)) return 'Every node value is an integer between -40000 and 40000.';
  return null;
}

