  let best = 0;
  function dfs(node) {
    if (node === null) {
      return [true, Infinity, -Infinity, 0];
    }
    const [leftIsBST, leftMin, leftMax, leftSum] = dfs(node.left);
    const [rightIsBST, rightMin, rightMax, rightSum] = dfs(node.right);
    if (leftIsBST && rightIsBST && leftMax < node.val && node.val < rightMin) {
      const sum = leftSum + node.val + rightSum;
      best = Math.max(best, sum);
      const low = Math.min(leftMin, node.val);
      const high = Math.max(rightMax, node.val);
      return [true, low, high, sum];
    }
    return [false, 0, 0, 0];
  }
  dfs(root);
  return best;
}

