function maxSumBST(root) {
  // Check the definition directly at every node and add up its subtree.
  const values = node => node === null ? [] : [...values(node.left), node.val, ...values(node.right)];
  const isBST = node => node === null || (
    values(node.left).every(v => v < node.val) &&
    values(node.right).every(v => v > node.val) &&
    isBST(node.left) && isBST(node.right));
  let best = 0;
  const visit = node => {
    if (node === null) return;
    if (isBST(node)) best = Math.max(best, values(node).reduce((a, b) => a + b, 0));
    visit(node.left);
    visit(node.right);
  };
  visit(root);
  return best;
}

