function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 12);
  // Random shape, sometimes starting with a long downward chain.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 300) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: 0, left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: 0, left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: 0, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // In-order values that mostly increase make large BST pieces; some nodes are then scrambled.
  const order = [];
  const stack = [];
  let current = 0;
  while (current !== null || stack.length) {
    while (current !== null) { stack.push(current); current = nodes[current].left; }
    current = stack.pop();
    order.push(current);
    current = nodes[current].right;
  }
  const limit = large ? 40000 : 10;
  const maxStep = large ? 80 : 3;
  const noise = [0, 0.02, 0.1, 0.4][Math.floor(rand() * 4)];
  let value = large ? -limit + Math.floor(rand() * 2000) : -limit + Math.floor(rand() * 14);
  for (const index of order) {
    nodes[index].val = Math.min(limit, value);
    value += Math.floor(rand() * (maxStep + 1));
  }
  for (const node of nodes) if (rand() < noise) node.val = Math.floor(rand() * (2 * limit + 1)) - limit;
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
